result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_binser.py", "content": """"Property-based tests for binser using Hypothesis."""

import pytest
from hypothesis import example, given, settings, strategies as st

from binser import deserialize, serialize

# Closed type family: None, bool, int, str, bytes + nested lists / dicts.
scalars = st.one_of(
    st.none(),
    st.booleans(),
    st.integers(),          # arbitrary-size signed ints
    st.text(),
    st.binary(),
)
objects = st.recursive(
    scalars,
    lambda children: st.one_of(
        st.lists(children),
        st.dictionaries(st.text(), children),
    ),
    max_leaves=25,
)


# --------------------------------------------------------------------------
# Round trip: deserialize(serialize(x)) == x, with type identity so that
# False is distinguished from 0, and both from "" (Python's `==` alone would
# happily conflate False == 0).
# --------------------------------------------------------------------------


@given(objects)
@example(None)
@example(False)
@example(True)
@example(0)
@example(-1)
@example("")
@example(b"\x00")
@example({"": False})
@example([0, False, "", None])
@settings(max_examples=500)
def test_roundtrip(x):
    encoded = serialize(x)
    decoded = deserialize(encoded)
    assert decoded == x
    # Distinguish look-alike-but-different-typed values across the family.
    assert type(decoded) is type(x)
    # Spot-check the specific confusions the tag scheme must avoid.
    if isinstance(x, bool) or x in (0, ""):
        assert isinstance(encoded[0], int)  # tag present
        assert not (isinstance(x, bool) and decoded == 0 and type(decoded) is int)
        assert not (x == 0 and type(x) is int and type(decoded) is bool)


@given(st.sampled_from([None, False, True, 0, 1, -1, "", "a", b"", b"\xff"]))
def test_scalar_tags_differ(x):
    """Distinct scalar values at risk of ==-conflation get distinct encodings."""
    encodings = {
        None: serialize(None),
        False: serialize(False),
        0: serialize(0),
        "": serialize(""),
        b"": serialize(b""),
    }
    distinct = {v for k, v in encodings.items()}
    assert len(distinct) == len(encodings), "look-alike scalars share encodings!"
    assert serialize(x) == encodings.get(x, serialize(x))


# --------------------------------------------------------------------------
# Determinism: equal objects produce equal bytes (in particular dicts built
# with different key insertion orders).
# --------------------------------------------------------------------------


@given(st.lists(objects, min_size=2, max_size=2))
@settings(max_examples=300)
def test_deterministic(pair):
    a, b = pair
    if a == b:
        assert serialize(a) == serialize(b)


@given(st.dictionaries(st.text(), objects))
@settings(max_examples=200)
def test_dict_key_order_irrelevant(d):
    shuffled = dict(sorted(d.items(), reverse=True))
    assert d == shuffled
    assert serialize(d) == serialize(shuffled)


# --------------------------------------------------------------------------
# Truncation: any proper prefix of a valid encoding must raise ValueError,
# never return garbage.
# --------------------------------------------------------------------------

NUM_CUTS = 12


@given(objects, st.data())
@settings(max_examples=300, deadline=None)
def test_truncated_prefixes_raise(x, data):
    encoded = serialize(x)
    n = len(encoded)
    if n == 0:  # impossible with this format (every value has >= 1 tag byte)
        return
    if n <= NUM_CUTS + 1:
        cuts = list(range(n))  # exhaustive: every proper prefix
    else:
        picks = data.draw(
            st.sets(st.integers(0, n - 1), min_size=NUM_CUTS, max_size=NUM_CUTS)
        )
        picks.update({0, n - 1})  # always cover the extremes
        cuts = sorted(picks)
    for k in cuts:
        prefix = encoded[:k]
        with pytest.raises(ValueError):
            deserialize(prefix)


@given(objects)
@settings(max_examples=100)
def test_single_byte_prefix_of_nested_value_raises(x):
    """The 1-byte prefix is a truncation for anything but bare None/bool-ish."""
    encoded = serialize(x)
    needs_more = not (
        len(encoded) == 1 or (len(encoded) == 2 and isinstance(x, bool))
    )
    if needs_more:
        with pytest.raises(ValueError):
            deserialize(encoded[:1])


# --------------------------------------------------------------------------
# Corrupt-tag robustness (adjacent to truncation: never garbage).
# --------------------------------------------------------------------------


@given(objects)
@settings(max_examples=100)
def test_unknown_tag_raises(x):
    bad = bytes([0xFF]) + serialize(x)[1:]
    with pytest.raises(ValueError):
        deserialize(bad)


@given(objects, st.integers(min_value=1, max_value=4))
@settings(max_examples=100, deadline=None)
def test_extra_trailing_garbage_raises(x, pad):
    with pytest.raises(ValueError):
        deserialize(serialize(x) + b"\xa5" * pad)
